final class DetailViewController: UIViewController {

    override func viewDidLoad() {
        super.viewDidLoad()
        // Once. Build the hierarchy, set constraints, configure fonts and colours.
        view.addSubview(titleLabel)
        NSLayoutConstraint.activate(constraints)
    }

    override func viewWillAppear(_ animated: Bool) {
        super.viewWillAppear(animated)
        // Every appearance. Refresh anything that may have changed while away.
        titleLabel.text = store.currentTitle
        navigationController?.setNavigationBarHidden(false, animated: animated)
    }

    override func viewDidAppear(_ animated: Bool) {
        super.viewDidAppear(animated)
        // Transition is finished: safe to start animations, log the screen view,
        // or become first responder.
        analytics.screenViewed("detail")
    }

    override func viewDidLayoutSubviews() {
        super.viewDidLayoutSubviews()
        // Bounds are final — set anything that depends on actual size.
        gradientLayer.frame = header.bounds
    }
}

// Any responder can opt in by simply implementing the action
final class CardView: UIView {
    override var canBecomeFirstResponder: Bool { true }

    @objc func markAsRead(_ sender: Any?) { … }

    override func canPerformAction(_ action: Selector, withSender sender: Any?) -> Bool {
        action == #selector(markAsRead) ? true : super.canPerformAction(action, withSender: sender)
    }
}

// nil-target: "whoever in the chain handles this"
UIApplication.shared.sendAction(#selector(CardView.markAsRead), to: nil, from: self, for: nil)

// Dismissing the keyboard is the same trick — resign whoever is first responder
UIApplication.shared.sendAction(
    #selector(UIResponder.resignFirstResponder), to: nil, from: nil, for: nil
)
